import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { BedDouble, CalendarDays, ChartNoAxesCombined, Check, ChevronDown, ChevronLeft, ChevronRight, ClipboardList, CreditCard, DoorOpen, FileText, LogOut, Menu, Plus, Search, Sparkles, Users, X, Building2, Moon, Sun, CircleDollarSign } from 'lucide-react';
import { api, patch, post, type User } from './lib/api';

type Room = { id: string; number: string; type: string; status: string; baseRate: number | string; notes?: string | null; stays?: Stay[] };
type Guest = { id: string; firstName: string; lastName: string; phone?: string | null; email?: string | null; nationality?: string | null; idType?: string | null; idNumber?: string | null; notes?: string | null; preferences?: string | null };
type Reservation = { id: string; confirmationCode: string; arrivalDate: string; departureDate: string; source: string; status: string; nightlyRate: number | string; depositAmount: number | string; depositMethod?: string; cancellationNote?: string | null; guest: Guest; room?: Room | null; roomId?: string | null; roomType?: string | null; groupName?: string | null; groupCode?: string | null };
type Stay = { id: string; status: string; guest: Guest; room: Room; checkInAt: string; expectedCheckOut: string; nightlyRate: number | string; folio?: { id: string; folioNumber: string; items: { amount: number | string }[]; payments: { amount: number | string }[] } | null };
type Task = { id: string; title: string; type: string; status: string; notes?: string | null; room: Room; assignedTo?: { name: string } | null };
type Dashboard = { date: string; arrivals: Reservation[]; departures: Stay[]; occupancy: { occupied: number; total: number; percent: number }; inHouse: number; openHousekeepingTasks: number; paymentsToday: number; rooms: Room[] };
type Page = 'Overview' | 'Rooms' | 'Reservations' | 'Guests' | 'In-house' | 'Housekeeping' | 'Reports' | 'Team';
const statusLabels: Record<string, string> = { AVAILABLE: 'Available', OCCUPIED: 'Occupied', DIRTY: 'Dirty', CLEAN: 'Clean', INSPECTED: 'Inspected', OUT_OF_ORDER: 'Out of order', CONFIRMED: 'Confirmed', PENDING: 'Pending', CHECKED_IN: 'Checked in', CHECKED_OUT: 'Checked out', CANCELLED: 'Cancelled', OPEN: 'Open', IN_PROGRESS: 'In progress', DONE: 'Done' };
const nav: { label: Page; icon: typeof DoorOpen }[] = [{ label: 'Overview', icon: ChartNoAxesCombined }, { label: 'Rooms', icon: BedDouble }, { label: 'Reservations', icon: CalendarDays }, { label: 'Guests', icon: Users }, { label: 'In-house', icon: DoorOpen }, { label: 'Housekeeping', icon: Sparkles }, { label: 'Reports', icon: FileText }, { label: 'Team', icon: ClipboardList }];
const today = () => new Date().toLocaleDateString('en-CA');
const money = (value: number | string | undefined) => new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(Number(value ?? 0));
const dateLabel = (value?: string | null, options: Intl.DateTimeFormatOptions = { month: 'short', day: 'numeric' }) => value ? new Date(`${value.slice(0,10)}T12:00:00`).toLocaleDateString(undefined, options) : '—';
const guestName = (guest: Guest) => `${guest.firstName} ${guest.lastName}`;

export default function App() {
  const [user, setUser] = useState<User | null>(() => { try { return JSON.parse(localStorage.getItem('hms_user') ?? 'null'); } catch { return null; } });
  const [page, setPage] = useState<Page>(() => user?.role === 'HOUSEKEEPING' ? 'Housekeeping' : 'Overview');
  const [mobileNav, setMobileNav] = useState(false);
  const [notice, setNotice] = useState('');
  const [modal, setModal] = useState<ReactNode>(null);
  const [version, setVersion] = useState(0);
  const [dark, setDark] = useState(false);
  const [date, setDate] = useState(today());
  const refresh = () => setVersion(v => v + 1);
  const flash = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 3500); };
  const onMutation = async (action: () => Promise<unknown>, done: string) => { try { await action(); setModal(null); flash(done); refresh(); } catch (e) { flash(e instanceof Error ? e.message : 'Could not save changes'); } };
  const logout = useCallback(() => { localStorage.removeItem('hms_token'); localStorage.removeItem('hms_user'); setUser(null); setModal(null); }, []);
  useEffect(() => { window.addEventListener('hms:logout', logout); return () => window.removeEventListener('hms:logout', logout); }, [logout]);
  useEffect(() => {
    const navigate = (event: Event) => { const next = (event as CustomEvent<Page>).detail; if (next) setPage(next); };
    const toast = (event: Event) => { setNotice(String((event as CustomEvent).detail ?? 'Done')); window.setTimeout(() => setNotice(''), 3500); };
    const walkin = () => setModal(<CheckInModal onClose={() => setModal(null)} onSave={onMutation}/>);
    window.addEventListener('hms:navigate', navigate); window.addEventListener('hms:toast', toast); window.addEventListener('hms:open-walkin', walkin);
    return () => { window.removeEventListener('hms:navigate', navigate); window.removeEventListener('hms:toast', toast); window.removeEventListener('hms:open-walkin', walkin); };
  });

  if (!user) return <Login onLogin={(u) => { setUser(u); if(u.role==='HOUSEKEEPING')setPage('Housekeeping'); }} />;
  return <div className={`app-shell ${dark ? 'dark-mode' : ''}`}>
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><Building2 size={18}/></div><div><strong>Staywell</strong><small>HOTEL DESK</small></div></div>
      <div className="property-pill"><span className="online-dot"/> Front desk <ChevronDown size={14}/></div>
      <div className="nav-caption">WORKSPACE</div>
      <nav>{nav.filter(({label})=>user.role!=='HOUSEKEEPING'||['Rooms','Housekeeping'].includes(label)).filter(({label})=>label!=='Team'||['ADMIN','MANAGER'].includes(user.role)).map(({ label, icon: Icon }) => <button className={`nav-item ${page === label ? 'active' : ''}`} key={label} onClick={() => { setPage(label); setMobileNav(false); }}><Icon size={18}/><span>{label}</span>{label === 'Housekeeping' && <span className="nav-count">!</span>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="sidebar-help"><div className="help-icon"><Sparkles size={16}/></div><strong>Everything in order?</strong><span>Keep today's operations moving smoothly.</span></div><div className="user-chip"><div className="avatar">{user.name.split(' ').map(x => x[0]).slice(0,2).join('')}</div><div className="user-meta"><strong>{user.name}</strong><span>{statusLabels[user.role] ?? user.role}</span></div><button aria-label="Sign out" className="icon-button logout" onClick={logout}><LogOut size={16}/></button></div></div>
    </aside>
    {mobileNav && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)}/>}
    <main className="main-area">
      <header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileNav(!mobileNav)}><Menu size={20}/></button><div className="breadcrumbs">Workspace <span>/</span> <strong>{page}</strong></div><div className="top-actions"><div className="top-date"><CalendarDays size={16}/>{dateLabel(date, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}</div><button className="icon-button" aria-label="Toggle theme" onClick={() => setDark(!dark)}>{dark ? <Sun size={17}/> : <Moon size={17}/>}</button><div className="avatar avatar-small">{user.name.slice(0,1)}</div></div></header>
      <div className="page-content">
        {page === 'Overview' && <Overview key={`overview-${version}-${date}`} date={date} setDate={setDate} openCheckIn={(r) => setModal(<CheckInModal reservation={r} onClose={() => setModal(null)} onSave={onMutation}/>)} openFolio={(s) => setModal(<FolioModal stay={s} onClose={() => setModal(null)} flash={flash}/>)} />}
        {page === 'Rooms' && <RoomsPage key={`rooms-${version}`} flash={flash} />}
        {page === 'Reservations' && <ReservationsPage key={`reservations-${version}`} openCheckIn={(r) => setModal(<CheckInModal reservation={r} onClose={() => setModal(null)} onSave={onMutation}/>)} />}
        {page === 'Guests' && <GuestsPage key={`guests-${version}`} flash={flash} />}
        {page === 'In-house' && <><InHousePage key={`inhouse-${version}`} openFolio={(s) => setModal(<FolioModal stay={s} onClose={() => setModal(null)} flash={flash}/>)} flash={flash} /><RoomMovePanel key={`room-move-${version}`} flash={flash} refresh={refresh}/></>}
        {page === 'Housekeeping' && <><HousekeepingPage key={`housekeeping-${version}`} flash={flash} /><TaskAssignment key={`task-assign-${version}`} flash={flash} refresh={refresh}/></>}
        {page === 'Reports' && <><ReportsPage key={`reports-${version}`} flash={flash} />{['ADMIN','MANAGER'].includes(user.role)&&<ActivityLog key={`audit-${version}`}/>}</>}
        {page === 'Team' && <TeamPage key={`team-${version}`} flash={flash} />}
      </div>
    </main>
    {modal}
    {notice && <div className="toast"><span className="toast-icon"><Check size={15}/></span>{notice}<button onClick={() => setNotice('')}><X size={15}/></button></div>}
  </div>;
}

function Login({ onLogin }: { onLogin: (user: User) => void }) {
  const [email, setEmail] = useState(''), [password, setPassword] = useState(''), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { const result = await api<{token:string;user:User}>('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); localStorage.setItem('hms_token', result.token); localStorage.setItem('hms_user', JSON.stringify(result.user)); onLogin(result.user); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to sign in'); } finally { setBusy(false); } }
  return <div className="login-wrap"><div className="login-art"><div className="login-brand"><div className="brand-mark"><Building2 size={18}/></div> Staywell</div><div className="art-copy"><span className="eyebrow">A CALM START TO EVERY STAY</span><h1>Good hospitality<br/>starts right here.</h1><p>Your hotel's daily operations, thoughtfully organized.</p></div><div className="art-bottom"><span>ROOMS · GUESTS · OPERATIONS</span><span>12 rooms, one clear view.</span></div><div className="art-shape shape-one"/><div className="art-shape shape-two"/></div><div className="login-form-side"><form className="login-form" onSubmit={submit}><div className="login-mobile-brand"><div className="brand-mark"><Building2 size={18}/></div> Staywell</div><span className="eyebrow">HOTEL TEAM</span><h2>Welcome back</h2><p>Sign in to continue to the front desk.</p><label>Email address<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)}/></label>{error && <div className="form-error">{error}</div>}<button className="primary-button full" disabled={busy}>{busy ? 'Signing in…' : 'Sign in'}<ChevronRight size={17}/></button><small className="login-foot">Your account is managed by your hotel administrator.</small></form></div></div>;
}

function PageTitle({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle?: string; action?: ReactNode }) { return <div className="page-title-row"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{subtitle && <p>{subtitle}</p>}</div>{action}</div>; }
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`card ${className}`}>{children}</section>; }
function SectionHeading({ title, meta, action }: { title: string; meta?: string; action?: ReactNode }) { return <div className="section-heading"><div><h3>{title}</h3>{meta && <span>{meta}</span>}</div>{action}</div>; }
function Badge({ value }: { value: string }) { const key = value.toLowerCase().replaceAll('_','-'); return <span className={`badge badge-${key}`}>{statusLabels[value] ?? value.replaceAll('_',' ')}</span>; }
function Empty({ title, copy }: { title: string; copy: string }) { return <div className="empty-state"><div className="empty-icon"><Sparkles size={19}/></div><strong>{title}</strong><span>{copy}</span></div>; }
function Loading() { return <div className="loading"><span className="spinner"/> Loading hotel data…</div>; }
function Field({ label, children, className = '' }: { label: string; children: ReactNode; className?: string }) { return <label className={`field ${className}`}><span>{label}</span>{children}</label>; }
function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) { return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section className={`modal ${wide ? 'modal-wide' : ''}`}><div className="modal-head"><div><h2>{title}</h2>{subtitle && <span>{subtitle}</span>}</div><button className="icon-button" onClick={onClose}><X size={18}/></button></div>{children}</section></div>; }

function Overview({ date, setDate, openCheckIn, openFolio }: { date: string; setDate: (d:string)=>void; openCheckIn:(r:Reservation)=>void; openFolio:(s:Stay)=>void }) {
  const { data, loading, error } = useLoad<Dashboard>(`/reports/dashboard?date=${date}`);
  if (loading) return <Loading/>;
  if (!data) return <ErrorPanel message={error}/>;
  const statuses = ['AVAILABLE','OCCUPIED','DIRTY','CLEAN','INSPECTED','OUT_OF_ORDER'];
  return <><PageTitle eyebrow={new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).toUpperCase()} title="Good morning, team" subtitle="Here's what's happening at the hotel today." action={<div className="date-picker"><button className="icon-button" onClick={()=>setDate(shiftDay(date,-1))}><ChevronLeft size={17}/></button><input type="date" value={date} onChange={e=>setDate(e.target.value)}/><button className="icon-button" onClick={()=>setDate(shiftDay(date,1))}><ChevronRight size={17}/></button></div>}/>
    <div className="stats-grid"><StatCard label="Occupancy" value={`${data.occupancy.percent}%`} note={`${data.occupancy.occupied} of ${data.occupancy.total} rooms`} icon={<BedDouble/>} tone="green"/><StatCard label="Arrivals" value={data.arrivals.length} note="Expected today" icon={<DoorOpen/>} tone="blue"/><StatCard label="Departures" value={data.departures.length} note="Expected today" icon={<LogOut/>} tone="peach"/><StatCard label="Payments today" value={money(data.paymentsToday)} note="Across all tenders" icon={<CircleDollarSign/>} tone="lilac"/></div>
    <div className="overview-grid"><Card><SectionHeading title="Today's arrivals" meta={`${data.arrivals.length} expected`} action={<button className="text-button" onClick={()=>{}}>View all <ChevronRight size={15}/></button>}/>{data.arrivals.length ? <div className="arrival-list">{data.arrivals.slice(0,5).map(r=><div className="arrival-row" key={r.id}><div className="avatar avatar-guest">{r.guest.firstName[0]}{r.guest.lastName[0]}</div><div className="arrival-person"><strong>{guestName(r.guest)}</strong><span>{r.confirmationCode} · {r.room?.number ? `Room ${r.room.number}` : r.roomType ?? 'Room to assign'}</span></div><div className="arrival-date">{dateLabel(r.arrivalDate)}</div><button className="small-button" onClick={()=>openCheckIn(r)}>Check in</button></div>)}</div>:<Empty title="No arrivals today" copy="The front desk is all caught up."/>}</Card>
    <Card className="room-overview-card"><SectionHeading title="Room status" meta="Live overview" action={<button className="text-button" onClick={()=>window.dispatchEvent(new CustomEvent('hms:navigate',{detail:'Rooms'}))}>Room board <ChevronRight size={15}/></button>}/><div className="status-summary">{statuses.map(s=><div className="status-summary-row" key={s}><span className={`status-dot dot-${s.toLowerCase()}`}/><span>{statusLabels[s]}</span><strong>{data.rooms.filter(r=>r.status===s).length}</strong></div>)}</div><div className="occupancy-footer"><div><span>Currently in-house</span><strong>{data.inHouse} <small>/ {data.occupancy.total} rooms</small></strong></div><div className="progress-track"><span style={{width:`${data.occupancy.percent}%`}}/></div></div></Card>
    <Card className="stays-card"><SectionHeading title="Guests in-house" meta={`${data.inHouse} active stays`} action={<button className="text-button" onClick={()=>window.dispatchEvent(new CustomEvent('hms:navigate',{detail:'In-house'}))}>View stays <ChevronRight size={15}/></button>}/><InHouseMini openFolio={openFolio}/></Card>
    <Card className="quick-card"><div className="quick-heading"><div className="quick-icon"><Sparkles size={17}/></div><div><h3>Front desk pulse</h3><span>A quick look at today's operations</span></div></div><div className="pulse-stat"><span>Housekeeping tasks open</span><strong>{data.openHousekeepingTasks}</strong></div><div className="pulse-stat"><span>Room revenue collection</span><strong>{money(data.paymentsToday)}</strong></div><div className="pulse-note"><span className="online-dot"/> All hotel services are running normally</div></Card></div>
  </>;
}
function StatCard({label,value,note,icon,tone}:{label:string;value:ReactNode;note:string;icon:ReactNode;tone:string}) { return <div className="stat-card"><div className={`stat-icon icon-${tone}`}>{icon}</div><span className="stat-label">{label}</span><strong className="stat-value">{value}</strong><span className="stat-note">{note}</span></div>; }
function InHouseMini({ openFolio }: { openFolio:(s:Stay)=>void }) { const {data,loading}=useLoad<Stay[]>('/stays/in-house'); if(loading)return <Loading/>;if(!data?.length)return <Empty title="No guests checked in" copy="Checked-in guests will appear here."/>;return <div className="mini-stay-list">{data.slice(0,4).map(s=><button className="mini-stay" key={s.id} onClick={()=>openFolio(s)}><span className="avatar avatar-guest">{s.guest.firstName[0]}{s.guest.lastName[0]}</span><span className="mini-stay-name"><strong>{guestName(s.guest)}</strong><small>Room {s.room.number} · departs {dateLabel(s.expectedCheckOut)}</small></span><ChevronRight size={16}/></button>)}</div>; }

function RoomsPage({ flash }: { flash:(s:string)=>void }) {
  const { data: rooms, loading, error, reload } = useLoad<Room[]>('/rooms');
  async function change(room:Room,status:string){try{await patch(`/rooms/${room.id}/status`,{status});flash(`Room ${room.number} marked ${statusLabels[status]?.toLowerCase()}`);reload();}catch(e){flash(e instanceof Error?e.message:'Could not update room');}}
  return <><PageTitle eyebrow="PROPERTY" title="Room board" subtitle="A clear, live view of every room in your hotel." action={<div className="room-count-pill"><BedDouble size={15}/> 12 rooms</div>}/>{loading?<Loading/>:!rooms?<ErrorPanel message={error}/>:<><div className="room-legend">{['AVAILABLE','OCCUPIED','DIRTY','CLEAN','INSPECTED','OUT_OF_ORDER'].map(s=><span key={s}><i className={`status-dot dot-${s.toLowerCase()}`}/>{statusLabels[s]}</span>)}</div><div className="room-grid">{rooms.map(room=><article className={`room-card room-${room.status.toLowerCase()}`} key={room.id}><div className="room-card-top"><span className="room-number">{room.number}</span><Badge value={room.status}/></div><div className="room-type">{room.type} room <span>·</span> {money(room.baseRate)} / night</div>{room.stays?.[0]?.guest && <div className="room-guest"><div className="avatar avatar-guest">{room.stays[0].guest.firstName[0]}{room.stays[0].guest.lastName[0]}</div><span><strong>{guestName(room.stays[0].guest)}</strong><small>Currently staying</small></span></div>}{room.notes && <p className="room-notes">{room.notes}</p>}<div className="room-card-bottom"><select aria-label={`Update room ${room.number} status`} value={room.status} onChange={e=>change(room,e.target.value)}><option value="AVAILABLE">Available</option><option value="OCCUPIED">Occupied</option><option value="DIRTY">Dirty</option><option value="CLEAN">Clean</option><option value="INSPECTED">Inspected</option><option value="OUT_OF_ORDER">Out of order</option></select></div></article>)}</div></>}</>;
}

function ReservationsPage({ openCheckIn }: { openCheckIn:(r:Reservation)=>void }) {
  const [mode,setMode]=useState<'day'|'month'>('day'), [month,setMonth]=useState(today().slice(0,7)), [query,setQuery]=useState(''),[editing,setEditing]=useState<Reservation|null>(null);
  const from = mode==='month' ? `${month}-01` : today(), to = mode==='month' ? shiftMonth(month,1)+'-01' : shiftDay(today(),31);
  const {data:reservations,loading,error,reload}=useLoad<Reservation[]>(`/reservations?from=${from}&to=${to}`);
  const {data:rooms}=useLoad<Room[]>('/rooms');
  const filtered=useMemo(()=>reservations?.filter(r=>`${guestName(r.guest)} ${r.confirmationCode} ${r.groupName??''}`.toLowerCase().includes(query.toLowerCase())),[reservations,query]);
  const create = async (e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const guestText=String(f.get('guest')).trim().split(/\s+/);try{await post('/reservations',{guest:{firstName:guestText[0],lastName:guestText.slice(1).join(' ')||'Guest',phone:f.get('phone')||undefined},source:f.get('source'),arrivalDate:f.get('arrival'),departureDate:f.get('departure'),roomId:f.get('room')||undefined,roomType:f.get('roomType')||undefined,nightlyRate:Number(f.get('rate')),depositAmount:Number(f.get('deposit')||0),depositMethod:f.get('depositMethod'),adults:Number(f.get('adults')||1),groupName:f.get('groupName')||undefined,groupCode:f.get('groupName')?String(f.get('groupName')).toUpperCase().replaceAll(' ','-'):undefined});form.reset();reload();window.dispatchEvent(new CustomEvent('hms:toast',{detail:'Reservation created'}));}catch(err){window.dispatchEvent(new CustomEvent('hms:toast',{detail:err instanceof Error?err.message:'Could not create reservation'}));}};
  return <><PageTitle eyebrow="FRONT DESK" title="Reservations" subtitle="Manage phone bookings, walk-ins and group stays." action={<button className="primary-button" onClick={()=>document.getElementById('new-reservation')?.scrollIntoView({behavior:'smooth'})}><Plus size={16}/> New reservation</button>}/><div className="toolbar"><div className="segmented"><button className={mode==='day'?'selected':''} onClick={()=>setMode('day')}>Daily</button><button className={mode==='month'?'selected':''} onClick={()=>setMode('month')}>Monthly board</button></div><div className="month-control"><button className="icon-button" onClick={()=>setMonth(shiftMonth(month,-1))}><ChevronLeft size={17}/></button><strong>{new Date(`${month}-15T12:00:00`).toLocaleDateString(undefined,{month:'long',year:'numeric'})}</strong><button className="icon-button" onClick={()=>setMonth(shiftMonth(month,1))}><ChevronRight size={17}/></button></div><div className="search-box"><Search size={16}/><input placeholder="Search guest or group" value={query} onChange={e=>setQuery(e.target.value)}/></div></div>
  {mode==='month' && rooms && filtered && <MonthlyBoard rooms={rooms} reservations={filtered.filter(r=>!['CANCELLED','NO_SHOW'].includes(r.status))} month={month}/>}
  {mode==='day' && <Card className="table-card"><SectionHeading title="Reservation list" meta={`${filtered?.length??0} upcoming stays`}/>{loading?<Loading/>:!filtered?<ErrorPanel message={error}/>:filtered.length===0?<Empty title="No reservations in this period" copy="Create a reservation to get started."/>:<div className="table-wrap"><table><thead><tr><th>Guest</th><th>Dates</th><th>Room</th><th>Source</th><th>Deposit</th><th>Status</th><th></th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td><strong>{guestName(r.guest)}</strong><small>{r.confirmationCode}{r.groupName?` · ${r.groupName}`:''}{r.cancellationNote?` · ${r.cancellationNote}`:''}</small></td><td>{dateLabel(r.arrivalDate)} – {dateLabel(r.departureDate)}</td><td>{r.room?.number?`Room ${r.room.number}`:r.roomType??'Unassigned'}</td><td><span className="source-label">{r.source.replace('_',' ')}</span></td><td>{money(r.depositAmount)}</td><td><Badge value={r.status}/></td><td>{['CONFIRMED','PENDING'].includes(r.status)?<div className="reservation-actions"><button className="small-button" onClick={()=>openCheckIn(r)}>Check in</button><button className="icon-button" title="Cancel reservation" onClick={async()=>{if(!window.confirm(`Cancel ${r.confirmationCode}?`))return;const note=window.prompt('Cancellation note (optional)');if(note===null)return;try{await post(`/reservations/${r.id}/cancel`,{note});reload();}catch{}}}><X size={16}/></button></div>:null}</td></tr>)}</tbody></table></div>}</Card>}
  <Card className="create-res-card" id="new-reservation"><SectionHeading title="Create a reservation" meta="Phone, walk-in, or group booking"/><form className="form-grid" onSubmit={create}><Field label="Guest name"><input name="guest" placeholder="Full name" required/></Field><Field label="Phone"><input name="phone" placeholder="Phone number"/></Field><Field label="Booking source"><select name="source"><option value="PHONE">Phone booking</option><option value="WALK_IN">Walk-in</option><option value="GROUP">Group booking</option></select></Field><Field label="Group name (optional)"><input name="groupName" placeholder="e.g. Regional workshop"/></Field><Field label="Arrival"><input name="arrival" type="date" defaultValue={today()} required/></Field><Field label="Departure"><input name="departure" type="date" defaultValue={shiftDay(today(),1)} required/></Field><Field label="Room (optional)"><select name="room"><option value="">Assign later</option>{rooms?.map(r=><option value={r.id} key={r.id}>{r.number} · {r.type}</option>)}</select></Field><Field label="Room type"><input name="roomType" placeholder="Standard, twin…"/></Field><Field label="Nightly rate"><input name="rate" type="number" min="0" step="0.01" defaultValue="0" required/></Field><Field label="Deposit received"><input name="deposit" type="number" min="0" step="0.01" defaultValue="0"/></Field><Field label="Deposit method"><select name="depositMethod"><option value="CASH">Cash</option><option value="MOBILE_MONEY">Mobile money</option><option value="CARD">Card</option><option value="BANK_TRANSFER">Bank transfer</option></select></Field><Field label="Adults"><input name="adults" type="number" min="1" defaultValue="1"/></Field><div className="form-actions"><button className="primary-button"><Plus size={16}/> Save reservation</button></div></form></Card>
  {reservations?.some(r=>['CONFIRMED','PENDING'].includes(r.status))&&<Card className="edit-res-card"><SectionHeading title="Edit a reservation" meta="Change dates, room assignment, or deposit details"/><Field label="Select reservation"><select value="" onChange={e=>setEditing(reservations.find(r=>r.id===e.target.value)??null)}><option value="">Choose a reservation to edit</option>{reservations.filter(r=>['CONFIRMED','PENDING'].includes(r.status)).map(r=><option key={r.id} value={r.id}>{r.confirmationCode} · {guestName(r.guest)} · {dateLabel(r.arrivalDate)}</option>)}</select></Field></Card>}{editing&&<EditReservationModal reservation={editing} rooms={rooms??[]} onClose={()=>setEditing(null)} onSaved={()=>{setEditing(null);reload();}}/>}
  </>;
}
function EditReservationModal({reservation,rooms,onClose,onSaved}:{reservation:Reservation;rooms:Room[];onClose:()=>void;onSaved:()=>void}){const [error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);setError('');try{await patch(`/reservations/${reservation.id}`,{arrivalDate:f.get('arrival'),departureDate:f.get('departure'),roomId:f.get('room')||null,nightlyRate:Number(f.get('rate')),depositAmount:Number(f.get('deposit')),depositMethod:f.get('depositMethod'),notes:f.get('notes')||undefined});onSaved();}catch(e){setError(e instanceof Error?e.message:'Unable to update reservation');}finally{setBusy(false);}}return <Modal title="Edit reservation" subtitle={`${guestName(reservation.guest)} · ${reservation.confirmationCode}`} onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="form-grid two"><Field label="Arrival"><input name="arrival" type="date" defaultValue={reservation.arrivalDate.slice(0,10)} required/></Field><Field label="Departure"><input name="departure" type="date" defaultValue={reservation.departureDate.slice(0,10)} required/></Field><Field label="Room"><select name="room" defaultValue={reservation.roomId??''}><option value="">Unassigned</option>{rooms.map(r=><option key={r.id} value={r.id}>{r.number} · {r.type}</option>)}</select></Field><Field label="Nightly rate"><input name="rate" type="number" min="0" step="0.01" defaultValue={Number(reservation.nightlyRate)} required/></Field><Field label="Deposit"><input name="deposit" type="number" min="0" step="0.01" defaultValue={Number(reservation.depositAmount)}/></Field><Field label="Deposit method"><select name="depositMethod" defaultValue={reservation.depositMethod??'CASH'}><option value="CASH">Cash</option><option value="MOBILE_MONEY">Mobile money</option><option value="CARD">Card</option><option value="BANK_TRANSFER">Bank transfer</option></select></Field><Field label="Notes"><input name="notes" defaultValue="" placeholder="Reservation notes"/></Field></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={busy}><Check size={16}/>{busy?'Saving…':'Save changes'}</button></div></form></Modal>;}
function MonthlyBoard({rooms,reservations,month}:{rooms:Room[];reservations:Reservation[];month:string}) { const count=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();const days=Array.from({length:count},(_,i)=>i+1);return <Card className="month-board-card"><div className="month-board-scroll"><table className="month-board"><thead><tr><th>Room</th>{days.map(d=><th key={d}>{d}</th>)}</tr></thead><tbody>{rooms.map(room=><tr key={room.id}><th>{room.number}<small>{room.type}</small></th>{days.map(d=>{const date=`${month}-${String(d).padStart(2,'0')}`;const res=reservations.find(r=>r.roomId===room.id&&r.arrivalDate.slice(0,10)<=date&&r.departureDate.slice(0,10)>date);return <td key={d}>{res&&<div className={`board-stay ${res.source.toLowerCase()}`} title={`${guestName(res.guest)} · ${res.confirmationCode}`}>{res.arrivalDate.slice(0,10)===date?res.guest.firstName:'·'}</div>}</td>})}</tr>)}</tbody></table></div><div className="board-legend"><span><i className="board-swatch confirmed"/>Reserved</span><span><i className="board-swatch walk-in"/>Walk-in</span><span>Click a stay in daily view to check in</span></div></Card>; }

function CheckInModal({reservation,onClose,onSave}:{reservation?:Reservation;onClose:()=>void;onSave:(a:()=>Promise<unknown>,s:string)=>void}) { const {data:rooms}=useLoad<Room[]>('/rooms');const [roomId,setRoomId]=useState(reservation?.roomId??'');const [image,setImage]=useState<File|null>(null);const {data:freeRooms}=useLoad<Room[]>('/rooms');const available=freeRooms?.filter(r=>!['OCCUPIED','DIRTY','OUT_OF_ORDER'].includes(r.status))??[];async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);onSave(async()=>{const result=await post<{stay:Stay;guest:Guest}>('/stays/check-in',{reservationId:reservation?.id,guestId:reservation?.guest.id,guest:reservation?undefined:{firstName:form.get('firstName'),lastName:form.get('lastName'),phone:form.get('phone')},roomId,expectedCheckOut:form.get('departure'),nightlyRate:Number(form.get('rate')||0),adults:Number(form.get('adults')||1),idType:form.get('idType')||undefined,idNumber:form.get('idNumber')||undefined});if(image){const data=new FormData();data.set('image',image);data.set('documentType',String(form.get('idType')||'OTHER'));try{await api(`/guests/${result.guest.id}/documents`,{method:'POST',body:data});}catch{window.dispatchEvent(new CustomEvent('hms:toast',{detail:'Check-in is complete, but the ID photo did not upload. Retry it from the guest profile when storage is available.'}));}}return result;},'Guest checked in');}
 return <Modal title="Check in guest" subtitle={reservation?`${guestName(reservation.guest)} · ${reservation.confirmationCode}`:'Walk-in guest'} onClose={onClose}><form className="modal-form" onSubmit={submit}>{!reservation&&<div className="form-grid two"><Field label="First name"><input name="firstName" required/></Field><Field label="Last name"><input name="lastName" required/></Field><Field label="Phone"><input name="phone"/></Field></div>}<Field label="Assign room"><select required value={roomId} onChange={e=>setRoomId(e.target.value)}><option value="">Choose a room</option>{available.map(r=><option value={r.id} key={r.id}>{r.number} · {r.type} · {statusLabels[r.status]}</option>)}</select></Field><div className="form-grid two"><Field label="Expected departure"><input name="departure" type="date" defaultValue={reservation?.departureDate.slice(0,10)??shiftDay(today(),1)} required/></Field><Field label="Nightly rate"><input name="rate" type="number" min="0" step="0.01" defaultValue={Number(reservation?.nightlyRate??rooms?.find(r=>r.id===roomId)?.baseRate??0)} required/></Field><Field label="Adults"><input name="adults" type="number" min="1" defaultValue="1"/></Field><Field label="ID type"><select name="idType"><option value="">Choose type</option><option value="NATIONAL_ID">National ID</option><option value="PASSPORT">Passport</option><option value="DRIVERS_LICENSE">Driver's license</option><option value="OTHER">Other</option></select></Field><Field label="ID number"><input name="idNumber"/></Field><Field label="ID photo (private)"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setImage(e.target.files?.[0]??null)}/></Field></div><div className="privacy-note"><span className="lock-dot"/> ID photos are compressed before private storage. Access is limited to authorized staff.</div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button"><Check size={16}/> Complete check-in</button></div></form></Modal>;
}

function GuestsPage({flash}:{flash:(s:string)=>void}) {
  const [query,setQuery]=useState(''),[selected,setSelected]=useState<string|null>(null),[version,setVersion]=useState(0),[editing,setEditing]=useState(false);
  const {data:guests,loading}=useLoad<Guest[]>(`/guests?q=${encodeURIComponent(query)}`,[query,version]);
  const {data:detail}=useLoad<any>(selected?`/guests/${selected}`:null,[selected,version]);
  return <><PageTitle eyebrow="RELATIONSHIPS" title="Guests" subtitle="Guest profiles, preferences and stay history." action={<div className="search-box guest-search"><Search size={16}/><input placeholder="Name, phone, ID number" value={query} onChange={e=>setQuery(e.target.value)}/></div>}/><div className="guest-layout"><Card className="guest-list-card"><SectionHeading title="Guest directory" meta={`${guests?.length??0} guests`}/>{loading?<Loading/>:guests?.length?<div className="guest-list">{guests.map(g=><button className={`guest-list-item ${selected===g.id?'selected':''}`} onClick={()=>setSelected(g.id)} key={g.id}><span className="avatar avatar-guest">{g.firstName[0]}{g.lastName[0]}</span><span><strong>{guestName(g)}</strong><small>{g.phone??g.email??'No contact details'}</small></span><ChevronRight size={16}/></button>)}</div>:<Empty title="No guests found" copy="Try another name or phone number."/>}</Card><Card className="guest-detail-card">{detail?<><div className="guest-profile-head"><div className="avatar avatar-large">{detail.firstName[0]}{detail.lastName[0]}</div><div><h2>{guestName(detail)}</h2><p>{detail.phone??'No phone'}{detail.nationality?` · ${detail.nationality}`:''}</p></div><button className="secondary-button" onClick={()=>setEditing(true)}>Edit profile</button></div><div className="guest-insight-grid"><Metric label="Total stays" value={detail.insights.totalStays}/><Metric label="Total nights" value={detail.insights.totalNights}/><Metric label="Total spent" value={money(detail.insights.totalSpent)}/><Metric label="Last stay" value={dateLabel(detail.insights.lastStayDate)}/></div><div className="guest-info-grid"><div><span>ID document</span><strong>{detail.idType?`${statusLabels[detail.idType]??detail.idType} · ${detail.idNumber??'no number'}`:'Not recorded'}</strong></div><div><span>Preferences</span><strong>{detail.preferences??'No preferences noted'}</strong></div><div><span>Notes</span><strong>{detail.notes??'No notes'}</strong></div></div><SectionHeading title="Stay history" meta={`${detail.stays.length} stays`}/>{detail.stays.length?<div className="table-wrap"><table><thead><tr><th>Dates</th><th>Room</th><th>Status</th><th>Paid</th></tr></thead><tbody>{detail.stays.map((s:any)=><tr key={s.id}><td>{dateLabel(s.checkInAt)} – {dateLabel(s.checkOutAt??s.expectedCheckOut)}</td><td>{s.room.number}</td><td><Badge value={s.status}/></td><td>{money(s.folio?.payments.reduce((n:number,p:any)=>n+Number(p.amount),0))}</td></tr>)}</tbody></table></div>:<Empty title="No stay history yet" copy="Completed visits will appear here."/>}<SectionHeading title="ID documents"/>{detail.documents.length?<div className="document-list">{detail.documents.map((doc:any)=><button className="document-item" key={doc.id} onClick={async()=>{try{const {url}=await api<{url:string}>(`/guests/documents/${doc.id}/url`);window.open(url,'_blank','noopener');}catch(e){flash(e instanceof Error?e.message:'Unable to open document');}}}><FileText size={17}/><span>{statusLabels[doc.documentType]??doc.documentType} · {Math.round(doc.sizeBytes/1024)} KB</span><span>View securely <ChevronRight size={14}/></span></button>)}</div>:<p className="subtle-copy">No ID image stored for this guest.</p>}<GuestDocumentUpload guestId={detail.id} onUploaded={()=>setVersion(v=>v+1)}/></>:<Empty title="Select a guest" copy="Choose a profile to see stay history and guest insights."/>}</Card></div>{editing&&detail&&<GuestEditModal guest={detail} onClose={()=>setEditing(false)} onSaved={()=>{setEditing(false);setVersion(x=>x+1);flash('Guest profile updated');}}/>}</>;
}
function GuestDocumentUpload({guestId,onUploaded}:{guestId:string;onUploaded:()=>void}){const [file,setFile]=useState<File|null>(null),[type,setType]=useState('NATIONAL_ID'),[busy,setBusy]=useState(false),[error,setError]=useState('');return <form className="document-upload" onSubmit={async e=>{e.preventDefault();if(!file)return;setBusy(true);setError('');const data=new FormData();data.set('image',file);data.set('documentType',type);try{await api(`/guests/${guestId}/documents`,{method:'POST',body:data});setFile(null);onUploaded();}catch(e){setError(e instanceof Error?e.message:'Unable to upload ID photo');}finally{setBusy(false);}}}><SectionHeading title="Add an ID photo" meta="Private storage · compressed to WebP"/><div className="form-grid two"><Field label="Document type"><select value={type} onChange={e=>setType(e.target.value)}><option value="NATIONAL_ID">National ID</option><option value="PASSPORT">Passport</option><option value="DRIVERS_LICENSE">Driver's license</option><option value="OTHER">Other</option></select></Field><Field label="Photo"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setFile(e.target.files?.[0]??null)}/></Field><div className="form-actions"><button className="secondary-button" disabled={!file||busy}><Plus size={15}/>{busy?'Uploading…':'Upload ID photo'}</button></div></div>{error&&<div className="form-error">{error}</div>}</form>;}
function GuestEditModal({guest,onClose,onSaved}:{guest:Guest;onClose:()=>void;onSaved:()=>void}){const [error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);try{await patch(`/guests/${guest.id}`,{firstName:f.get('firstName'),lastName:f.get('lastName'),phone:f.get('phone'),email:f.get('email')||null,nationality:f.get('nationality'),idType:f.get('idType')||null,idNumber:f.get('idNumber')||null,preferences:f.get('preferences')||null,notes:f.get('notes')||null});onSaved();}catch(e){setError(e instanceof Error?e.message:'Could not update guest');}finally{setBusy(false);}}return <Modal title="Edit guest profile" subtitle={guestName(guest)} onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="form-grid two"><Field label="First name"><input name="firstName" defaultValue={guest.firstName} required/></Field><Field label="Last name"><input name="lastName" defaultValue={guest.lastName} required/></Field><Field label="Phone"><input name="phone" defaultValue={guest.phone??''}/></Field><Field label="Email"><input name="email" type="email" defaultValue={guest.email??''}/></Field><Field label="Nationality"><input name="nationality" defaultValue={guest.nationality??''}/></Field><Field label="ID type"><select name="idType" defaultValue={guest.idType??''}><option value="">Not recorded</option><option value="NATIONAL_ID">National ID</option><option value="PASSPORT">Passport</option><option value="DRIVERS_LICENSE">Driver's license</option><option value="OTHER">Other</option></select></Field><Field label="ID number"><input name="idNumber" defaultValue={guest.idNumber??''}/></Field><Field label="Preferences"><input name="preferences" defaultValue={guest.preferences??''}/></Field><Field label="Notes" className="wide-field"><input name="notes" defaultValue={guest.notes??''}/></Field></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={busy}><Check size={16}/>{busy?'Saving…':'Save profile'}</button></div></form></Modal>;}
function Metric({label,value}:{label:string;value:ReactNode}){return <div className="metric-card"><span>{label}</span><strong>{value}</strong></div>;}

function InHousePage({openFolio,flash}:{openFolio:(s:Stay)=>void;flash:(s:string)=>void}) { const {data:stays,loading,error,reload}=useLoad<Stay[]>('/stays/in-house');return <><PageTitle eyebrow="GUEST SERVICES" title="Guests in-house" subtitle="Active stays, folios and room assignments." action={<button className="primary-button" onClick={()=>window.dispatchEvent(new CustomEvent('hms:open-walkin'))}><Plus size={16}/> Walk-in check-in</button>}/>{loading?<Loading/>:!stays?<ErrorPanel message={error}/>:stays.length===0?<Card><Empty title="No guests checked in" copy="New arrivals will show up here after check-in."/></Card>:<div className="inhouse-grid">{stays.map(s=><Card className="inhouse-card" key={s.id}><div className="inhouse-card-top"><div className="avatar avatar-guest">{s.guest.firstName[0]}{s.guest.lastName[0]}</div><Badge value="OCCUPIED"/></div><h3>{guestName(s.guest)}</h3><span className="inhouse-room">Room {s.room.number} · {s.room.type}</span><div className="inhouse-dates"><div><span>CHECKED IN</span><strong>{dateLabel(s.checkInAt)}</strong></div><div><span>EXPECTED OUT</span><strong>{dateLabel(s.expectedCheckOut)}</strong></div></div><div className="folio-mini"><span>{s.folio?.folioNumber??'Folio'} · Balance</span><strong>{money((s.folio?.items.reduce((n,x)=>n+Number(x.amount),0)??0)-(s.folio?.payments.reduce((n,x)=>n+Number(x.amount),0)??0))}</strong></div><div className="inhouse-actions"><button className="secondary-button" onClick={()=>openFolio(s)}><CreditCard size={15}/> Folio</button><button className="small-button" onClick={async()=>{if(!window.confirm(`Check out ${guestName(s.guest)} from room ${s.room.number}?`))return;try{await post(`/stays/${s.id}/check-out`,{});flash('Guest checked out · room marked dirty');reload();}catch(e){flash(e instanceof Error?e.message:'Could not check out');}}}>Check out</button></div></Card>)}</div>}</>; }

function FolioModal({stay,onClose,flash}:{stay:Stay;onClose:()=>void;flash:(s:string)=>void}) {
  const [v,setV]=useState(0);
  const {data:folio}=useLoad<any>(stay.folio?`/billing/folio/${stay.folio.id}`:null,[stay.id,v]);
  if(!stay.folio)return <Modal title="Folio" onClose={onClose}><Empty title="No folio found" copy="This stay has no billing folio."/></Modal>;
  const charge=folio?.summary?.charges??0,paid=folio?.summary?.paid??0;
  async function record(action:()=>Promise<unknown>,message:string){try{await action();setV(x=>x+1);flash(message);}catch(e){flash(e instanceof Error?e.message:'Could not update folio');}}
  async function printInvoice(){try{const inv=await api<any>(`/billing/folio/${folio.id}/invoice`);const w=window.open('','_blank');if(w){w.document.write(`<title>Invoice ${escapeHtml(inv.folioNumber)}</title><style>body{font:15px Arial;max-width:750px;margin:50px auto;color:#21342d}h1{color:#245b49}table{width:100%;border-collapse:collapse;margin:30px 0}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}</style><h1>${escapeHtml(inv.hotel)}</h1><h2>Invoice ${escapeHtml(inv.folioNumber)}</h2><p>${escapeHtml(inv.guest.firstName)} ${escapeHtml(inv.guest.lastName)} · Room ${escapeHtml(inv.room.number)}</p><table><tr><th>Item</th><th class="right">Amount</th></tr>${inv.items.map((i:any)=>`<tr><td>${escapeHtml(i.description)}</td><td class="right">${money(i.amount)}</td></tr>`).join('')}</table><p>Total ${money(inv.total)} · Paid ${money(inv.paid)} · Balance ${money(inv.balance)}</p><script>window.print()</script>`);w.document.close();}}catch(e){flash(e instanceof Error?e.message:'Unable to create invoice');}}
  return <Modal title={`Guest folio · ${stay.folio.folioNumber}`} subtitle={`${guestName(stay.guest)} · Room ${stay.room.number}`} onClose={onClose} wide><div className="folio-body">{!folio?<Loading/>:<><div className="folio-summary"><Metric label="Charges" value={money(charge)}/><Metric label="Paid" value={money(paid)}/><Metric label="Balance due" value={money(charge-paid)}/></div><div className="table-wrap"><table><thead><tr><th>Description</th><th>Qty</th><th>Price</th><th>Amount</th></tr></thead><tbody>{folio.items.map((i:any)=><tr key={i.id}><td>{i.description}</td><td>{Number(i.quantity)}</td><td>{money(i.unitPrice)}</td><td>{money(i.amount)}</td></tr>)}</tbody></table></div><SectionHeading title="Payments"/>{folio.payments.map((p:any)=><div className="payment-row" key={p.id}><span>{statusLabels[p.method]??p.method.replace('_',' ')}{p.reference?` · ${p.reference}`:''}</span><strong>{money(p.amount)}</strong></div>)}<div className="folio-actions"><button className="secondary-button" onClick={()=>record(async()=>{const desc=window.prompt('Charge description (e.g. breakfast, laundry)');if(!desc)return;const amount=Number(window.prompt('Amount'));if(!amount)return;await post(`/billing/folio/${folio.id}/items`,{description:desc,unitPrice:amount,quantity:1,type:'EXTRA'});},'Charge added')}><Plus size={15}/> Add charge</button><button className="secondary-button" onClick={()=>record(async()=>{const amount=Number(window.prompt(`Payment amount (balance ${money(charge-paid)})`));if(!amount)return;const method=window.prompt('Payment method: CASH, MOBILE_MONEY, CARD, BANK_TRANSFER','CASH')?.toUpperCase();if(!method)return;await post(`/billing/folio/${folio.id}/payments`,{amount,method});},'Payment recorded')}><CreditCard size={15}/> Record payment</button><button className="primary-button" onClick={printInvoice}><FileText size={15}/> Print invoice</button></div></>}</div></Modal>;
}

function HousekeepingPage({flash}:{flash:(s:string)=>void}) {const {data:tasks,loading,error,reload}=useLoad<Task[]>('/housekeeping/tasks');const {data:rooms}=useLoad<Room[]>('/rooms');const [filter,setFilter]=useState('ALL');const visible=tasks?.filter(t=>filter==='ALL'||t.type===filter);return <><PageTitle eyebrow="ROOM OPERATIONS" title="Housekeeping" subtitle="Room turns, inspections and special requests." action={<button className="primary-button" onClick={()=>document.getElementById('new-task')?.scrollIntoView({behavior:'smooth'})}><Plus size={16}/> Add task</button>}/><div className="toolbar"><div className="segmented">{['ALL','CLEANING','INSPECTION','MAINTENANCE','SPECIAL_REQUEST'].map(v=><button className={filter===v?'selected':''} key={v} onClick={()=>setFilter(v)}>{v==='ALL'?'All tasks':statusLabels[v]??v.replace('_',' ')}</button>)}</div></div>{loading?<Loading/>:!tasks?<ErrorPanel message={error}/>:visible?.length?<div className="task-list">{visible.map(t=><Card className="task-card" key={t.id}><div className="task-room"><div className={`task-room-icon ${t.type==='MAINTENANCE'?'maintenance':''}`}>{t.type==='MAINTENANCE'?<ClipboardList size={18}/>:<BedDouble size={18}/>}</div><div><strong>Room {t.room.number}</strong><span>{t.room.type} · {statusLabels[t.type]??t.type}</span></div></div><div className="task-copy"><strong>{t.title}</strong><span>{t.notes??'No additional notes'}</span></div><div className="task-assignee">{t.assignedTo?.name??'Unassigned'}</div><select value={t.status} onChange={async e=>{try{await patch(`/housekeeping/tasks/${t.id}`,{status:e.target.value});flash(e.target.value==='DONE'?'Task completed · room status updated':'Task updated');reload();}catch(err){flash(err instanceof Error?err.message:'Could not update task');}}}><option value="OPEN">Open</option><option value="IN_PROGRESS">In progress</option><option value="DONE">Complete</option></select></Card>)}</div>:<Card><Empty title="Housekeeping is all caught up" copy="New checkout turnovers and tasks appear here."/></Card>}<Card className="create-task-card" id="new-task"><SectionHeading title="Create a task"/><form className="form-grid" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post('/housekeeping/tasks',{roomId:f.get('roomId'),title:f.get('title'),type:f.get('type'),notes:f.get('notes')});(e.target as HTMLFormElement).reset();flash('Housekeeping task created');reload();}catch(err){flash(err instanceof Error?err.message:'Could not create task');}}}><Field label="Room"><select name="roomId" required><option value="">Choose room</option>{rooms?.map(r=><option key={r.id} value={r.id}>{r.number} · {r.type}</option>)}</select></Field><Field label="Task type"><select name="type"><option value="CLEANING">Cleaning</option><option value="INSPECTION">Inspection</option><option value="MAINTENANCE">Maintenance</option><option value="SPECIAL_REQUEST">Special request</option></select></Field><Field label="Task"><input name="title" required placeholder="e.g. Prepare extra towels"/></Field><Field label="Notes"><input name="notes" placeholder="Details for the team"/></Field><div className="form-actions"><button className="primary-button"><Plus size={16}/> Add task</button></div></form></Card></>; }

function ReportsPage({flash}:{flash:(s:string)=>void}) {const {data:insights,loading}=useLoad<any>('/reports/guest-insights');const [dates,setDates]=useState({from:today().slice(0,7)+'-01',to:today()});const [revenue,setRevenue]=useState<any>(null);const [busy,setBusy]=useState(false);const run=async()=>{setBusy(true);try{setRevenue(await api(`/reports/revenue?from=${dates.from}&to=${dates.to}`));}catch(e){flash(e instanceof Error?e.message:'Could not load report');}finally{setBusy(false);}};useEffect(()=>{void run();},[]);const close=async()=>{try{const report=await post<any>('/reports/daily-close',{businessDate:today()});flash(`Daily close completed · payments ${money(report.paymentsTotal)}`);}catch(e){flash(e instanceof Error?e.message:'Unable to close day');}};return <><PageTitle eyebrow="INSIGHTS" title="Reports" subtitle="Revenue, occupancy trends and your most valued guests." action={<button className="secondary-button" onClick={close}><Check size={16}/> Close today</button>}/><Card className="revenue-card"><SectionHeading title="Revenue & occupancy" meta="Based on posted charges and stays"/><div className="report-filters"><Field label="From"><input type="date" value={dates.from} onChange={e=>setDates({...dates,from:e.target.value})}/></Field><Field label="To"><input type="date" value={dates.to} onChange={e=>setDates({...dates,to:e.target.value})}/></Field><button className="primary-button" onClick={run} disabled={busy}>{busy?'Loading…':'Run report'}</button></div>{revenue&&<div className="report-metrics"><Metric label="Room revenue" value={money(revenue.roomRevenue)}/><Metric label="Extras & adjustments" value={money(revenue.otherRevenue)}/><Metric label="Payments received" value={money(revenue.payments)}/><Metric label="Occupied room nights" value={revenue.occupiedNights}/><Metric label="Occupancy" value={`${revenue.occupancyPercent}%`}/></div>}</Card>{loading?<Loading/>:insights&&<><div className="report-columns"><GuestRank title="Top guests · stays" items={insights.topByStays} value="totalStays" unit="stays"/><GuestRank title="Top guests · nights" items={insights.topByNights} value="totalNights" unit="nights"/><GuestRank title="Top guests · revenue" items={insights.topByRevenue} value="totalSpent" unit="spent"/></div><Card className="repeat-card"><SectionHeading title="Most recent repeat guests" meta={`${insights.repeatGuests.length} guests with 2+ stays`}/>{insights.recentRepeatGuests.length?<div className="table-wrap"><table><thead><tr><th>Guest</th><th>Stays</th><th>Nights</th><th>Total spent</th><th>Last stay</th></tr></thead><tbody>{insights.recentRepeatGuests.map((g:any)=><tr key={g.id}><td><strong>{g.name}</strong><small>{g.phone??''}</small></td><td>{g.totalStays}</td><td>{g.totalNights}</td><td>{money(g.totalSpent)}</td><td>{dateLabel(g.lastStayDate)}</td></tr>)}</tbody></table></div>:<Empty title="No repeat stays yet" copy="Guests returning for a second stay will be listed here."/>}</Card></>}</>;}
function GuestRank({title,items,value,unit}:{title:string;items:any[];value:string;unit:string}){return <Card className="rank-card"><SectionHeading title={title}/>{items.length?items.slice(0,5).map((g,i)=><div className="rank-row" key={g.id}><span className={`rank-number ${i===0?'rank-first':''}`}>{String(i+1).padStart(2,'0')}</span><div><strong>{g.name}</strong><small>{g.totalStays} stays · last {dateLabel(g.lastStayDate)}</small></div><b>{value==='totalSpent'?money(g[value]):g[value]}<small>{unit==='spent'?'total':unit}</small></b></div>):<Empty title="No stays recorded" copy="Guest rankings will appear once stays are completed."/>}</Card>;}

function TeamPage({flash}:{flash:(s:string)=>void}) {const {data:users,loading,error,reload}=useLoad<any[]>('/users');return <><PageTitle eyebrow="PROPERTY SETTINGS" title="Team access" subtitle="Staff accounts and role assignments." action={<button className="primary-button" onClick={()=>document.getElementById('invite-staff')?.scrollIntoView({behavior:'smooth'})}><Plus size={16}/> Add staff member</button>}/><Card className="table-card"><SectionHeading title="Staff accounts" meta={`${users?.length??0} accounts`}/>{loading?<Loading/>:!users?<ErrorPanel message={error}/>:<div className="table-wrap"><table><thead><tr><th>Team member</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><div className="staff-name"><span className="avatar avatar-guest">{u.name.slice(0,1)}</span><strong>{u.name}</strong></div></td><td>{u.email}</td><td><Badge value={u.role}/></td><td><Badge value={u.active?'INSPECTED':'OUT_OF_ORDER'}/></td></tr>)}</tbody></table></div>}</Card><Card id="invite-staff"><SectionHeading title="Add staff member" meta="Managers and administrators can manage user access"/><form className="form-grid" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post('/users',{name:f.get('name'),email:f.get('email'),password:f.get('password'),role:f.get('role')});(e.target as HTMLFormElement).reset();flash('Staff account created');reload();}catch(err){flash(err instanceof Error?err.message:'Unable to create staff account');}}}><Field label="Full name"><input name="name" required/></Field><Field label="Email"><input name="email" type="email" required/></Field><Field label="Temporary password (10+ characters)"><input name="password" type="password" minLength={10} required/></Field><Field label="Role"><select name="role"><option value="RECEPTIONIST">Receptionist</option><option value="MANAGER">Manager</option><option value="HOUSEKEEPING">Housekeeping</option><option value="ADMIN">Admin</option></select></Field><div className="form-actions"><button className="primary-button"><Plus size={16}/> Create account</button></div></form></Card></>;}

function TaskAssignment({flash,refresh}:{flash:(s:string)=>void;refresh:()=>void}){const {data:tasks,reload}=useLoad<Task[]>('/housekeeping/tasks');const {data:staff}=useLoad<{id:string;name:string}[]>('/housekeeping/staff');const [taskId,setTaskId]=useState(''),[staffId,setStaffId]=useState('');return <Card className="assignment-card"><SectionHeading title="Assign housekeeping" meta="Route open room tasks to an active housekeeper"/><div className="form-grid two"><Field label="Open task"><select value={taskId} onChange={e=>setTaskId(e.target.value)}><option value="">Choose task</option>{tasks?.map(t=><option key={t.id} value={t.id}>Room {t.room.number} · {t.title}</option>)}</select></Field><Field label="Housekeeper"><select value={staffId} onChange={e=>setStaffId(e.target.value)}><option value="">Choose a team member</option>{staff?.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><div className="form-actions"><button className="primary-button" disabled={!taskId||!staffId} onClick={async()=>{try{await patch(`/housekeeping/tasks/${taskId}`,{assignedToId:staffId});flash('Task assigned');setTaskId('');setStaffId('');reload();refresh();}catch(e){flash(e instanceof Error?e.message:'Could not assign task');}}}><Check size={16}/> Assign task</button></div></div></Card>;}
function RoomMovePanel({flash,refresh}:{flash:(s:string)=>void;refresh:()=>void}){const {data:stays}=useLoad<Stay[]>('/stays/in-house');const {data:rooms}=useLoad<Room[]>('/rooms');const [stayId,setStayId]=useState(''),[roomId,setRoomId]=useState('');const selected=stays?.find(x=>x.id===stayId);const eligible=rooms?.filter(r=>r.id!==selected?.room.id&&!['OCCUPIED','DIRTY','OUT_OF_ORDER'].includes(r.status))??[];return <Card className="move-room-card"><SectionHeading title="Move a guest to another room" meta="The previous room will be marked Dirty and sent to housekeeping"/><div className="form-grid"><Field label="Current guest"><select value={stayId} onChange={e=>{setStayId(e.target.value);setRoomId('');}}><option value="">Choose an in-house guest</option>{stays?.map(s=><option key={s.id} value={s.id}>{guestName(s.guest)} · Room {s.room.number}</option>)}</select></Field><Field label="Destination room"><select value={roomId} onChange={e=>setRoomId(e.target.value)}><option value="">Choose an available room</option>{eligible.map(r=><option value={r.id} key={r.id}>{r.number} · {r.type}</option>)}</select></Field><div className="form-actions"><button className="primary-button" disabled={!stayId||!roomId} onClick={async()=>{try{await post(`/stays/${stayId}/move-room`,{roomId,reason:'Guest room move'});flash('Guest moved · previous room sent to housekeeping');setStayId('');setRoomId('');refresh();}catch(e){flash(e instanceof Error?e.message:'Could not move guest');}}}><DoorOpen size={16}/> Move guest</button></div></div></Card>;}
function ActivityLog(){const {data,loading,error}=useLoad<any[]>('/reports/audit-log');return <Card className="activity-card"><SectionHeading title="Recent activity" meta="Staff actions recorded by the system"/>{loading?<Loading/>:!data?<ErrorPanel message={error}/>:data.length?<div className="table-wrap"><table><thead><tr><th>When</th><th>Staff member</th><th>Action</th><th>Record</th></tr></thead><tbody>{data.slice(0,30).map(item=><tr key={item.id}><td>{new Date(item.createdAt).toLocaleString()}</td><td>{item.user?.name??'System'}</td><td>{item.action.replaceAll('.',' ').replaceAll('_',' ')}</td><td>{item.entityType}{item.entityId?` · ${item.entityId.slice(-7)}`:''}</td></tr>)}</tbody></table></div>:<Empty title="No activity recorded yet" copy="Important room, reservation, stay and billing changes will appear here."/>}</Card>;}

function useLoad<T>(path:string|null,deps:unknown[]=[]){const [data,setData]=useState<T|null>(null),[loading,setLoading]=useState(!!path),[error,setError]=useState(''),[tick,setTick]=useState(0);const reload=useCallback(()=>setTick(x=>x+1),[]);useEffect(()=>{if(!path){setLoading(false);setData(null);return;}let live=true;setLoading(true);api<T>(path).then(x=>{if(live){setData(x);setError('');}}).catch(e=>{if(live)setError(e instanceof Error?e.message:'Unable to load data');}).finally(()=>{if(live)setLoading(false);});return()=>{live=false;};},[path,tick,...deps]);return {data,loading,error,reload};}
function ErrorPanel({message}:{message:string}){return <Card><Empty title="Could not load this view" copy={message||'Please check your connection and try again.'}/></Card>;}
function shiftDay(value:string,amount:number){const d=new Date(`${value.slice(0,10)}T12:00:00`);d.setDate(d.getDate()+amount);return d.toLocaleDateString('en-CA');}
function shiftMonth(value:string,amount:number){const d=new Date(`${value}-15T12:00:00`);d.setMonth(d.getMonth()+amount);return d.toLocaleDateString('en-CA').slice(0,7);}
function escapeHtml(value:unknown){return String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]??character));}
